public abstract class Trabajo {
  //Se crean tipos Horario
    public enum Horario {
        DIURNO,
        NOCTURNO
    }
	//Se crean tipos Estado
    public enum EstadoTrabajo {
        EN_COLA,
        ASIGNADO,
        EN_EJECUCION,
        COMPLETADO,
        CANCELADO
    }

    protected String codigo;
    protected String estudio;
    protected String proyecto;
    protected double horasEstimadas;
    protected Horario horario;
    protected EstadoTrabajo estado;
    protected int intentos;
    protected double CargoIntento;
    protected double ingresoRegistro;
    protected double ingresoReintentos;

    public Trabajo(String codigo, String estudio, String proyecto,
                   double horasEstimadas, Horario horario) {

        // Rechaza códigos nulos, vacíos o formados solo por espacios.
        if (codigo == null || codigo.trim().isEmpty()) {
            throw new IllegalArgumentException(
                "El código no puede estar vacío."
            );
        }

        // Comprueba que las horas sean positivas y finitas.
        if (!Double.isFinite(horasEstimadas) || horasEstimadas <= 0) {
            throw new IllegalArgumentException(
                "Las horas estimadas deben ser positivas y finitas."
            );
        }

        // Comprueba que se haya seleccionado un horario.
        if (horario == null) {
            throw new IllegalArgumentException(
                "El horario es obligatorio."
            );
        }

        this.codigo = codigo.trim();
        this.estudio = estudio;
        this.proyecto = proyecto;
        this.horasEstimadas = horasEstimadas;
        this.horario = horario;

        this.estado = EstadoTrabajo.EN_COLA;
        this.intentos = 0;
        this.CargoIntento = 25.0;
        this.ingresoRegistro = 0.0;
        this.ingresoReintentos = 0.0;
    }

    // Cada subclase implementa su fórmula de costo.
    public abstract double calcularCosto();

    // Cada subclase determina su tiempo de entrega en horas.
    public abstract int calcularTiempoEntrega();

    // Cada subclase establece su máximo de intentos.
    public abstract int getIntentosMaximos();

    // Cada subclase proporciona su nombre de categoría.
    public abstract String getCategoria();

    // Permite cualquier nodo por defecto.
    public boolean esCompatibleCon(Nodo nodo) {
        // Las categorías con restricciones sobrescriben este método.
        return true;
    }

    // Obtiene la tarifa base según el horario.
    protected double tarifaBase() {
        // Comprueba si corresponde la tarifa diurna.
        if (horario == Horario.DIURNO) {
            // Devuelve la tarifa diurna.
            return 60.0;
        } else {
            // Devuelve la tarifa nocturna.
            return 40.0;
        }
    }

    // Devuelve el cargo adicional correspondiente al intento actual.
    public double getCargoReintento() {
        // Solo cobra a partir del segundo intento.
        if (intentos > 1) {
            return CargoIntento;
        } else {
            return 0.0;
        }
    }

    // Registra el costo del trabajo como ingreso por registro.
    public void cobrarRegistro() {
        // Evita cobrar nuevamente o cobrar después de asignar o ejecutar.
        if (ingresoRegistro != 0.0
                || estado != EstadoTrabajo.EN_COLA
                || intentos != 0) {
            throw new IllegalStateException(
                "El trabajo no permite un nuevo cobro de registro."
            );
        }

        double costo = calcularCosto();

        // Valida el costo antes de modificar los ingresos.
        if (!Double.isFinite(costo) || costo <= 0) {
            throw new IllegalArgumentException(
                "El costo debe ser positivo y finito."
            );
        }

        // Guarda el monto calculado por la subclase.
        ingresoRegistro = costo;
    }

    // Cambia un trabajo en cola a asignado.
    public void asignar() {
        // Rechaza trabajos que no estén disponibles en cola.
        if (estado != EstadoTrabajo.EN_COLA) {
            throw new IllegalStateException(
                "Solo se pueden asignar trabajos en cola."
            );
        } else {
            // Marca el trabajo como asignado a un lote.
            this.estado = EstadoTrabajo.ASIGNADO;
        }
    }

    // Devuelve un trabajo asignado a la cola.
    public void retirar() {
        // Solo permite retirar trabajos que estén asignados.
        if (estado != EstadoTrabajo.ASIGNADO) {
            throw new IllegalStateException(
                "Solo se pueden retirar trabajos asignados."
            );
        } else {
            // Lo deja disponible sin cambiar intentos ni ingresos.
            this.estado = EstadoTrabajo.EN_COLA;
        }
    }

    // Inicia un intento y devuelve el cargo adicional aplicado.
    public double iniciarEjecucion() {
        // Comprueba que el trabajo esté asignado.
        if (estado != EstadoTrabajo.ASIGNADO) {
            throw new IllegalStateException(
                "Solo se pueden ejecutar trabajos asignados."
            );
        }

        // Impide superar el número de intentos permitido.
        if (intentos >= getIntentosMaximos()) {
            throw new IllegalStateException(
                "El trabajo agotó sus intentos permitidos."
            );
        }

        // Incrementa antes de calcular el cargo del intento actual.
        intentos++;

        // Marca el trabajo como en ejecución.
        this.estado = EstadoTrabajo.EN_EJECUCION;

        double cargo = getCargoReintento();

        // Acumula Q0 en el primer intento y Q25 en los siguientes.
        ingresoReintentos += cargo;

        // Devuelve el cargo aplicado en este inicio.
        return cargo;
    }

    // Actualiza el estado según el resultado de la ejecución.
    public void registrarResultado(boolean completado) {
        // Solo admite resultados de un trabajo en ejecución.
        if (estado != EstadoTrabajo.EN_EJECUCION) {
            throw new IllegalStateException(
                "El trabajo no está en ejecución."
            );
        }

        // El éxito completa el trabajo, incluso en su último intento.
        if (completado) {
            this.estado = EstadoTrabajo.COMPLETADO;
        } else if (intentos >= getIntentosMaximos()) {
            // Un fallo sin intentos restantes cancela el trabajo.
            this.estado = EstadoTrabajo.CANCELADO;
        } else {
            // Un fallo con intentos disponibles lo devuelve a la cola.
            this.estado = EstadoTrabajo.EN_COLA;
        }
    }

    public String getCodigo() {
        return codigo;
    }

    public String getEstudio() {
        return estudio;
    }

    public String getProyecto() {
        return proyecto;
    }

    public double getHorasEstimadas() {
        return horasEstimadas;
    }

    public Horario getHorario() {
        return horario;
    }

    public EstadoTrabajo getEstado() {
        return estado;
    }

    public int getIntentos() {
        return intentos;
    }

    public double getIngresoRegistro() {
        return ingresoRegistro;
    }

    public double getIngresoReintentos() {
        return ingresoReintentos;
    }

    // Presenta los datos comunes del trabajo para consultas.
    @Override
    public String toString() {
        // Muestra los ingresos con dos decimales.
        return String.format(
            "Código: %s | Estudio: %s | Proyecto: %s"
            + " | Categoría: %s | Horas estimadas: %s"
            + " | Horario: %s | Estado: %s | Intentos: %d"
            + " | Ingreso por registro: Q%.2f"
            + " | Ingreso por reintentos: Q%.2f",
            codigo,
            estudio,
            proyecto,
            getCategoria(),
            horasEstimadas,
            horario,
            estado,
            intentos,
            ingresoRegistro,
            ingresoReintentos
        );
    }
}